  ...(caseResults.some((item) => !item.passed)
    ? caseResults.filter((item) => !item.passed).map((item) => `- \`${item.id}\` did not satisfy all manifest assertions; see its metrics and raw evidence.`)
    : ["- None recorded by the deterministic runner."]),
  "",
